// IN-DEPTH INSTRUCTIONS FOR RETRO 8-BIT GO CHASE GAME:
// 1. SETUP: Uses retro ASCII grid drawing for an 8-bit arcade look.
// 2. STATE: Tracks player '@' and lion 'L' positions on a 1D coordinate axis.
// 3. LOGIC: The player runs to the right, and the lion chases from the left.
// 4. LOOP: Simulates a tick cycle where the distance between player and lion changes.
package main
import (
	"fmt"
	"time"
)
func main() {
	fmt.Println("=== 8-BIT RETRO CHASE: RUN FROM THE LION! ===")
	fmt.Println("Instructions: Keep running to the right to escape!")
	fmt.Println()
	playerPos := 5
	lionPos := 0
	for tick := 0; tick < 6; tick++ {
		fmt.Printf("Tick %d [", tick)
		for p := 0; p < 20; p++ {
			if p == playerPos {
				fmt.Print("@")
			} else if p == lionPos {
				fmt.Print("L")
			} else {
				fmt.Print(".")
			}
		}
		fmt.Println("]")
		playerPos += 2
		lionPos += 1
		time.Sleep(150 * time.Millisecond)
	}
	fmt.Println()
	fmt.Println("Success! You successfully escaped the lion!")
}

package main
import "sort"
type LSMTree struct {
	memtable map[string]string
	sstables []map[string]string
}
func (l *LSMTree) Put(k, v string) {
	l.memtable[k] = v
	if len(l.memtable) >= 3 {
		l.sstables = append(l.sstables, l.memtable)
		l.memtable = make(map[string]string)
	}
}
func (l *LSMTree) Get(k string) string {
	if v, ok := l.memtable[k]; ok { return v }
	for i := len(l.sstables)-1; i >= 0; i-- {
		if v, ok := l.sstables[i][k]; ok { return v }
	}
	return ""
}

