package main
type Participant interface {
	Prepare(tx uint64) bool
	Commit(tx uint64)
	Abort(tx uint64)
}
type Coordinator2PC struct { participants []Participant }
func (c *Coordinator2PC) CommitTx(tx uint64) string {
	for _, p := range c.participants { if !p.Prepare(tx) { for _, p2 := range c.participants { p2.Abort(tx) }; return "Aborted" } }
	for _, p := range c.participants { p.Commit(tx) }
	return "Committed"
}

