import "hash/fnv"
type HashRouter struct { nodes []string }
func (h *HashRouter) Route(key string) string {
	alg := fnv.New32a()
	alg.Write([]byte(key))
	return h.nodes[int(alg.Sum32()) % len(h.nodes)]
}

