type RangeRouter struct { boundaries []struct{ Start, End, Node string } }
func (r *RangeRouter) Route(key string) string {
	for _, b := range r.boundaries {
		if key >= b.Start && key <= b.End { return b.Node }
	}
	return "Node-Fallback"
}

