type LinuxKfifo struct {
	buffer []interface{}
	size uint32
	in uint32
	out uint32
}
func (k *LinuxKfifo) Put(val interface{}) bool {
	k.buffer[k.in & (k.size - 1)] = val
	k.in++
	return true
}
func (k *LinuxKfifo) Get() interface{} {
	val := k.buffer[k.out & (k.size - 1)]
	k.out++
	return val
}

